        {%- endfor -%}
      {%- endif -%}
      <td class="cell{% if c.mark %} mark{% endif %}"{% if book.in_colour and c.when == "In" and l.direction == "In" %} style="color: {{ book.in_colour }}"{% endif %}>{{ cell.s|e }}
