    {%- if book.balance and brought is not none -%}{{ note("Balance brought forward: " ~ brought ~ ".") }}{%- endif -%}
    {%- for l in lines -%}
      {%- if l.kind in ("Opening", "Count") -%}
        {{ note("Entry " ~ l.number ~ ": " ~ ("opening balance " ~ l.qty if l.kind == "Opening" else "register count, " ~ ("+" if l.direction == "In" else "-") ~ l.qty) ~ (", balance " ~ l.balance if l.balance is not none else "") ~ ". Signed " ~ (l.signed_by_name or "") ~ ".") }}
