    {%- for p in range(10) if items.more -%}
      {%- set got = ivn_rows("Retail Register State", filters=[["book", "=", doc.book], ["register_store", "=", doc.register_store]], fields=["item", "item_name"], order_by="item asc", limit=200, start=p * 200) -%}
      {%- set items.rows = items.rows + got -%}{%- set items.more = got|length == 200 -%}
    {%- endfor -%}
    {%- for st in items.rows -%}
      {%- set ns = namespace(lines=[], more=true) -%}
      {%- for p in range(50) if ns.more -%}
        {%- set got = ivn_rows("Retail Register Line", filters=where + [["item", "=", st.item]], fields=book.fields, order_by="number asc", limit=200, start=p * 200) -%}
        {%- set ns.lines = ns.lines + got -%}{%- set ns.more = got|length == 200 -%}
