      {%- set before = ivn_rows("Retail Register Line", filters=[["book", "=", doc.book], ["register_store", "=", doc.register_store], ["item", "=", st.item], ["entry_date", "<", doc.from_date]], fields=["balance"], order_by="number desc", limit=1) -%}
      {%- set brought = before[0].balance if before else none -%}
      {%- if ns.lines or brought -%}{%- set any.page = true -%}<div class="item-page">{{ page(ns.lines, st.item_name, ns.more, brought) }}</div>{%- endif -%}
    {%- endfor -%}
    {%- if not any.page -%}{{ page([], none, false, none) }}{%- endif -%}
    {%- if items.more %}<p class="warn">This print stopped at 2,000 items: print each store's book on its own.</p>{% endif -%}
  {%- else -%}
    {%- set ns = namespace(lines=[], more=true) -%}
    {%- for p in range(50) if ns.more -%}
